import{_ as p,o as a,c as b,ae as t}from"./chunks/framework.BrEqZt6s.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/무제.md","filePath":"philosophy/무제.md"}'),e={name:"philosophy/무제.md"};function o(l,r,i,n,s,h){return a(),b("div",null,[...r[0]||(r[0]=[t('<h2 id="공자" tabindex="-1">공자 <a class="header-anchor" href="#공자" aria-label="Permalink to &quot;공자&quot;">​</a></h2><p>천하무도<br> 질서가 붕괴된 시대, 종법제와 이를 뒷받침하는 예가 존재<br> 더불어 살아야하는 존재<br> 사를 군자로 교육</p><p>인과 예<br> 인은 사람다움<br> 충과 서로 나뉨</p><p>예<br> 인의 실현, 사회적 규범<br> 극기복례<br> 공자는 <strong>&#39;형식적인 예&#39;가 아니라 &#39;내면의 인(仁)&#39;을 바탕으로 한 예의 회복</strong>을 주장했습니다.<br> 예와 법의 차이<br> 규범라는 점에서 비슷한 속성을 띔<br> 질서유지: 공동체 내의 갈드을 방지하고 공유된 사회적 관계를 형성한다<br> 행위의 기준: 무엇이 옳고 그른지에 대한 판단 근거 제공<br> 공익성 표방: 개인의 욕망을 조절하여 공동체의 안녕 도모</p><ol><li><p>규제 대상:<br> 예는 내면의 양심을 대상으로 함, 즉 행위가 일어나기 전의 마음가짐이나 태도를 규제. 행위자체보다 그 행위에 담긴 공경의 마음을 주로 봄<br> 법은 외면의 행위를 통제, 마음 속으로 누군가를 미워한다고 해서 처벌하지 않음</p></li><li><p>동력:<br> 예는 양심의 부끄러운 감정에 기반함. 스스로 부끄러움을 느끼게하여 자발적 교정을 유도<br> 법은 이기적 공포의 감정에 기반. 법은 위반했을때 닥칠 손해에 대한 공포심을 동력으로 삼으며, 인간의 이기적 본성을 전제에 두고 이를 억제하는 데 주력함</p></li><li><p>제재의 방식:<br> 예는 무례한 사람이라는 사회적 낙인을 통하여 공동체로부터의 소외나 관계의 단절의 형식으로 제재를 가함<br> 법은 물리적 강제와 박탈이 주된 제재</p></li><li><p>유연성의 측면<br> 예는 때와 장소, 상대에 따라 유연하게 다르며 맥락에 따른 최적의 중용을 찾고자함<br> 법은 법앞에 만인이 평등하다는 원칙아래에 누가 집행하더라도 동일한 경과가 나오는 일관성을 원칙으로 함.</p></li></ol><p>종법제도</p><p>공자가 『주례』의 시스템을 회복하려 했던 이유는 그것이 단순히 왕의 권력을 강화하기 위해서가 아니라, <strong>‘역할의 규정’을 통해 사회적 혼란을 잠재울 수 있다고 믿었기 때문</strong>입니다.</p><ul><li><p><strong>정명사상(正名思想):</strong> &quot;군군신신부부자자(君君臣臣父父子子)&quot;, 즉 임금은 임금답고, 신하는 신하답고, 아버지는 아버지답고, 자식은 자식다워야 한다는 것입니다. 『주례』는 각자가 사회에서 맡은 위치와 역할을 명확히 규정하여, 각자의 위치에서 본분을 다할 때 비로소 사회가 안정된다고 보았습니다.</p></li><li><p><strong>종법적 질서의 내면화:</strong> 『주례』는 혈연적 위계질서를 바탕으로 제사, 관직, 예법을 세세하게 정해두었습니다. 공자는 이 틀을 유지함으로써 인간 관계의 근본인 &#39;효(孝)&#39;와 &#39;제(悌)&#39;가 자연스럽게 사회 전체로 확장될 수 있다고 보았습니다.</p></li></ul><p>군자</p><p>덕치<br> 공동체의 리더가 몸소 도덕적 삶을 살아감으로 공동체 구성원들로 하여금 도덕적 삶을 살아갈 수 있도록 하는것.<br> 솔선수범의 정치가 공자의 덕치 정치</p><h2 id="맹자" tabindex="-1">맹자 <a class="header-anchor" href="#맹자" aria-label="Permalink to &quot;맹자&quot;">​</a></h2><p>인자 무적<br> 덕치 = 인치 = 왕도</p><p>사람은 누구나 불인인지심을 가짐<br> (타인의 고통이나 불행을 보고 차마 그대로 넘어가지 못하는 마음 )<br> 어린 아이가 우물로 기어가는 모습을 본다면 그 누구라도 차마 넘어가지 못할 것이다<br> 측은지심, 수오지심, 사양지심, 시비지심이 각각 인의예지의 단서이다</p><p>이러한 사단은 성선설의 근거</p><p>패도정치 대신 왕도정치를 주장<br> 덕을 바탕으로 백성의 마음을 얻어 다스림</p><p>왜 사람은 타락하는가</p><ol><li>시스템의 미비: 무항산, 무항심</li><li>수양의 무족: 본성을 잘 실행할 수 있도록 호연지기를 길러라</li></ol><p>역성혁명: 왕이 왕답지 못하면 교체해야 한다<br> 공자의 정명론. 군군신신부부자자</p><p>맹자<br> 올바름의 기준을 본성에서 찾음<br> 인간의 본성이 선하기 때문</p><hr><h2 id="순자" tabindex="-1">순자 <a class="header-anchor" href="#순자" aria-label="Permalink to &quot;순자&quot;">​</a></h2><p>성악설<br> 예를 통해 교화<br> 천인지분<br> 예는 성인의 실천으로 생기는 것<br> 예는 귀천을 매기고 나이 많은 사람과 적은 이의 차등이 있게 함<br> 신분에 따라 어울리는 대우를 함 -&gt; 상황에 맞는 욕망 실현 방법</p><p>상대적으로 국가를 부국하게 만드는 왕도 패자도 긍정<br> 맹자는 백성이 근본, 순자는 군자가 백성의 근본</p><p>순자는 내면에서 찾을 수 없음<br> 선의 가능성을 지니고 있지 않기 때문에<br> 따라서 덕치로 다스릴 수 없고 이떄문에 그 기준을 만들어야하나다<br> 똑똑한 사람이 예를 지정하여 이를 따르자</p><h2 id="묵자" tabindex="-1">묵자 <a class="header-anchor" href="#묵자" aria-label="Permalink to &quot;묵자&quot;">​</a></h2><p>왜 살기 힘든가? 전쟁이 나서<br> 왜 전쟁이 나는가? 별애 해서<br> 어떻게 해결할 것인가? 공동체의 이익증진<br> 어떻게? 근면한 노동과 알뜰한 소비 절용 절장</p><p>현자를 모으기 위해 현자를 높이 대우해야한다<br> 능력주의적, 관료의 공공성을 강조<br> 이러한 현자를 모아 기준을 통일해야한다 (사람마다 올바름의 기준이 달라서)<br> 백성은 선비를 기준으로 삼아 윗사람을 무조건 따라야함</p><p>도덕성의 기준<br> 공동체의 이익, 실적으로 이익이 없는 도덕은 공허함</p><p>겸상애 교상리<br> 공동체에 끼치는 해악의 정도가 클수록 큰 벌</p><p>모든 전쟁을 부정하는가?<br> 바로잡기 위한 전쟁이나 방어전쟁은 허용<br> 왜 이는 혀용하는가? 의로움이 중심이 아닌 공동체의 이익을 중심으로 삼기 떄문</p><p>이러한 겸상애 교상리는 하늘의 뜻</p><p>비명 숙명론 비판<br> 숙명론을 주장하게 되면 근면성실의 동력을 잃어버린다.<br> 인간의 노력 무력화.<br> 지배층의 무책임 정당화</p><h2 id="노자" tabindex="-1">노자 <a class="header-anchor" href="#노자" aria-label="Permalink to &quot;노자&quot;">​</a></h2><p>도에 따르는 것이 중요하다고 주장<br> 도법자연 자연을 본받아야한다고 주장<br> 도란 길을 의미, 우주의 법칙<br> 인간도 우주에 속하는 존재이기떄문에 도에 따라야함<br> 자연이란 nature가 아닌 스스로 그러함, 즉 본래성에 따라 스스로 그렇게 드러나도록 하는 것<br> 우주에서 자연을 거스르는 존재가 인간<br> 있는 그대로의 세계가 아닌 개념화를 통해 받아들임. 인간은 대상을 가치화를 하고 이에 주관적 가치를 대입. 이러한 가치가 부여됨에 따라 좋은 것을 가지려고 하기떄문에 이러한 욕망으로부터 갈등과 혼란이 발생</p><p>도가도 비상도 명가명 비상명<br> 말로 표현할 수 있는 도는 도가 아니며 이름붙힐 수 있는 이름은 영원한 이름이 아니다<br> 언어는 존재하는 대상을 온전히 표현할 수 없음</p><p>왜 도라고 부르는가<br> 도를 명확히 표현 할 수는 없지만 그것을 표현해야하기 때문</p><p>우주만물의 근원, 무규정적, 자연적질서, 정치와 삶의 기준</p><p>무위의 정치<br> 아무것도 하지 않는 것이 아님</p><p>소국과민</p>',39)])])}const _=p(e,[["render",o]]);export{c as __pageData,_ as default};
